  assert.strictEqual(slugify('  Cr\u00e8me   Br\u00fbl\u00e9e -- 2024 '), 'creme-brulee-2024');
  assert.strictEqual(slugify('a'.repeat(50)), 'a'.repeat(40));
  assert.strictEqual(slugify('a'.repeat(39) + ' bbb'), 'a'.repeat(39));
