  assert.strictEqual(uniqueSlug('Hello World', new Set(['hello-world'])), 'hello-world-2');
  assert.strictEqual(uniqueSlug('Hello World', new Set(['hello-world', 'hello-world-2', 'hello-world-3'])), 'hello-world-4');
